bench_run = function(d) {
	kk_pair_weights_rowsum = function(m_vec, row_weights) {
		row_weights = as.numeric(row_weights)
		n = length(row_weights)
		m_vec = if (is.null(m_vec)) rep(NA_integer_, n) else rep_len(as.integer(m_vec), n)
		in_pair = !is.na(m_vec) & m_vec > 0L
		pair_ids = sort(unique(m_vec[in_pair]))
		pair_weights = rep(NaN, length(pair_ids))
		ok = in_pair & !is.na(row_weights)
		if (any(ok)) {
			s = rowsum(row_weights[ok], m_vec[ok], reorder = TRUE)
			cnt = rowsum(rep(1, sum(ok)), m_vec[ok], reorder = TRUE)
			pair_weights[match(as.integer(rownames(s)), pair_ids)] = s[, 1] / cnt[, 1]
		}
		reservoir_idx = which(is.na(m_vec) | m_vec <= 0L)
		list(pair_ids = as.numeric(pair_ids), pair_weights = as.numeric(pair_weights),
			reservoir_idx = as.numeric(reservoir_idx), reservoir_weights = as.numeric(row_weights[reservoir_idx]))
	}
	kk_pair_weights_rowsum(d$m, d$row_weights)
}
